const paused = await page.locator("#playText").textContent();
await page.locator("#playBtn").click();
const resumed = await page.locator("#playText").textContent();
const canvas = page.locator("canvas");
const box = await canvas.boundingBox();
if (box) {
  await page.mouse.move(box.x + box.width * 0.54, box.y + box.height * 0.48);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width * 0.64, box.y + box.height * 0.43, { steps: 8 });
  await page.mouse.up();
  await page.mouse.wheel(0, -420);
}
await page.locator("#resetBtn").click();
await page.locator("#guideBtn").click();
await page.waitForTimeout(200);
const guide = await page.evaluate(() => ({
  visible: document.querySelector("#guideCard")?.classList.contains("visible"),
  heading: document.querySelector("#guideHeading")?.textContent
}));
await page.locator("#guideClose").click();
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(250);
const mobile = await page.evaluate(() => {
  const dock = document.querySelector(".control-dock").getBoundingClientRect();
  const status = document.querySelector(".status-panel").getBoundingClientRect();
  return {
    dockFits: dock.left >= 0 && dock.right <= innerWidth + 1 && dock.bottom <= innerHeight + 1,
    statusFits: status.left >= 0 && status.right <= innerWidth + 1,
    scrollWidth: document.documentElement.scrollWidth,
    viewport: innerWidth
  };
});
await page.setViewportSize({ width: 1440, height: 900 });
await page.locator('[data-system="split"]').click();
await page.locator('[data-mode="cooling"]').click();
await page.waitForTimeout(500);
const screenshot = await saveScreenshot(await page.screenshot(), "hvac-exhibit-validation.png");
console.log(JSON.stringify({ initial, monoblock, heating, paused, resumed, guide, mobile, errors, screenshot }, null, 2));
